def count_lines(s):
    n = s.count("\n")
    if n == 0:
        return 0 if s == "" else 1
    if not s.endswith("\n"):
        n = n + 1
    return n

def count_blank(s):
    c = 0
    for l in s.split("\n")[:-1]:
        if l.strip() == "":
            c = c + 1
    return c

